"""Render the lexer/interner comparison and diagnostic SSA investigation."""
import json
import pathlib

ROOT = pathlib.Path('suite/reports')
def read(name): return json.loads((ROOT/name).read_text())
p=read('c-frontend-optimized-20261015.json')
s=read('c-frontend-optimized-storage-20261015.json')
ssa=read('c-frontend-ssa-investigation-20261015.json')
stacks=read('c-frontend-optimized-stacks-20261015.json')
data={'summaries':{k:{'variants':v['variants']} for k,v in p['summaries'].items()},'aggregate':p['aggregate'],'memory':{k:{'allocation_call_reduction':v['allocation_call_reduction'],'baseline':{'peak_rss_bytes':v['baseline']['peak_rss_bytes']},'arena':{'peak_rss_bytes':v['arena']['peak_rss_bytes']}} for k,v in s['applications'].items()}}
rows=''.join(f'<tr><th>{app}</th><td>{d["totals"]["blocks"]:,}</td><td>{d["totals"]["block_visits"]:,}</td></tr>' for app,d in ssa['applications'].items())
q=stacks['stacks']['quickjs-ssa-outline']['category_percent']['ssa_predecessor_scan']
sql=stacks['stacks']['sqlite-ssa-outline']['category_percent']['ssa_predecessor_scan']
page=r'''<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><style>
*{box-sizing:border-box}body{margin:0;color:var(--foreground,#27272c);background:transparent;font:14px/1.5 var(--font-sans,system-ui)}h2{font-size:22px;letter-spacing:-.4px;margin:0 0 7px}h3{font-size:16px;margin:22px 0 10px}p{margin:6px 0 12px}.muted,small{color:var(--muted-foreground,#777)}.controls{display:flex;gap:8px;margin:15px 0}select{padding:7px 10px;background:transparent;color:inherit;border:1px solid var(--border,#ddd);border-radius:7px;font:inherit}.stats{display:grid;grid-template-columns:repeat(3,1fr);gap:10px;margin:14px 0}.stat{border:1px solid var(--border,#ddd);border-radius:8px;padding:13px}.stat strong{font-size:25px;display:block;line-height:1.35}.stat small{display:block;font-size:12px}.legend{display:flex;gap:14px;font-size:12px;flex-wrap:wrap;margin:15px 0}.legend span:before{content:'';display:inline-block;width:9px;height:9px;border-radius:2px;background:var(--c);margin-right:5px}.app{margin:15px 0}.label{display:flex;justify-content:space-between;margin-bottom:5px}.barrow{display:grid;grid-template-columns:42px 1fr;gap:8px;align-items:center;font-size:11px;color:var(--muted-foreground,#777);margin:4px 0}.track{height:16px;background:var(--muted,#eee);display:flex;overflow:hidden;border-radius:3px}.seg{height:100%}.columns{display:grid;grid-template-columns:1fr 1fr;gap:24px}.table{overflow:auto}table{border-collapse:collapse;width:100%;font-size:12px;font-variant-numeric:tabular-nums}th,td{text-align:right;padding:8px 4px;border-bottom:1px solid var(--border,#ddd)}th:first-child,td:first-child{text-align:left;padding-left:0}thead th{color:var(--muted-foreground,#777);font-weight:500}.box{border-top:1px solid var(--border,#ddd);padding-top:12px;margin-top:12px}.foot{font-size:11px;margin-top:20px}code{font-size:12px;overflow-wrap:anywhere}@media(max-width:520px){.stats{gap:6px}.stat{padding:8px}.stat strong{font-size:21px}.columns{grid-template-columns:1fr;gap:0}h2{font-size:20px}table{font-size:11px}}
</style></head><body><h2>Lexer rewrite + arena-backed frontend strings</h2><p class="muted">44 translation units · Lua / QuickJS / SQLite · Apple M5 Max</p><div class="controls"><select id="mode" aria-label="Compilation mode"><option value="False">Normal mode</option><option value="True">Debug-info mode</option></select></div><div class="stats"><div class="stat"><strong id="gain"></strong><small>less frontend time</small></div><div class="stat"><strong id="alloc"></strong><small>fewer allocation calls</small></div><div class="stat"><strong id="cleanup"></strong><small>less cleanup time</small></div></div><p id="interval" class="muted"></p><div class="legend" id="legend"></div><div id="chart"></div><div class="table"><table><thead><tr><th>Application</th><th>Compile API</th><th>Lex</th><th>Parse / types</th><th>Cleanup</th></tr></thead><tbody id="times"></tbody></table></div><small>Before → after, milliseconds per whole application. Bars sum stage medians and include IR generation; compile API medians are measured separately.</small><div class="columns"><section><h3>What changed</h3><p><strong>Byte-oriented lexing.</strong> Longest-match punctuation dispatch, identifier classification, bounded literal scanning and scalar decoding, borrowed line markers, cached file IDs, and allocation-free numeric case handling.</p><p><strong>One byte arena per compilation.</strong> Names and literal bytes are interned. Tokens are Copy; scopes, typed-tree names, labels, and initializers borrow stable arena storage. Only data needed by the returned IR becomes owned output.</p><p class="muted">Interning adds some lexer work on Lua and SQLite compared with the lexer-only variant. Parser and cleanup savings repay that cost. Remaining cleanup is mostly typed-tree and type ownership.</p></section><section><h3>Memory observations</h3><table><thead><tr><th>Application</th><th>Peak RSS, MiB</th></tr></thead><tbody id="memory"></tbody></table><p class="muted">Requested allocation bytes fall by about 7–10% in normal mode. RSS is one full counting-process observation per variant, including resident inputs and warmups; it is not isolated-call peak memory.</p></section></div><div class="box"><h3>SSA investigation: repeated graph scans confirmed</h3><table><thead><tr><th>Application</th><th>Blocks built</th><th>Block entries visited by find_preds</th></tr></thead><tbody>__SSA_ROWS__</tbody></table><p>SQLite's two largest scans are <code>sqlite3VdbeExec</code> (2.59 million visits) and <code>do_meta_command</code> (2.24 million). An outlined diagnostic attributes <strong>__Q__% of QuickJS</strong> and <strong>__SQL__% of SQLite</strong> frontend samples to predecessor discovery.</p><p><strong>Next target:</strong> maintain incoming edges as branches are constructed, while accounting for raw CFG mutations exposed by the builder API. SSA semantics remain unchanged in this pass. Counters and outlining were diagnostic builds; their timings are excluded from speedup claims.</p></div><p class="box"><strong>77 tests pass.</strong> All 44 normal and 44 debug-info IR snapshots match byte-for-byte across baseline, lexer-only, and full arena/interner variants. Generated IR verifies; the executable C fixture suite also passes.</p><p class="foot">Headline: equal-application geometric mean of paired public-compile ratios. Nine paired rounds per application and output mode. Public compile and staged APIs run serially with resident preprocessed input; mode/application order shuffled and variant order rotated. One host, warm caches. Preprocessing, optimizer, backend, reads, IR verification, process startup and returned-module destruction are outside latency. Allocation counters run separately. Six separate six-second samples include module destruction; the two SSA-outline captures only add inline(never) for attribution. No end-to-end compiler or other-machine speedup claim.</p><script>
const D=__DATA__,apps=['lua','quickjs','sqlite'],labels={lua:'Lua',quickjs:'QuickJS',sqlite:'SQLite'},keys=['lex_ms','parse_ms','irgen_ms','cleanup_ms'],names=['Lex','Parse / types','IR generation','Cleanup'],colors=['#4e9ad7','#41a88e','#e3a04f','#9099a6'];const mode=document.getElementById('mode');mode.onchange=draw;const fmt=n=>n.toFixed(1);document.getElementById('legend').innerHTML=names.map((n,i)=>'<span style="--c:'+colors[i]+'">'+n+'</span>').join('');function draw(){const m=mode.value,agg=D.aggregate['arena:'+m],entries=apps.map(app=>{const s=D.summaries[app+':'+m];return{app,s,b:s.variants.baseline,a:s.variants.arena,memory:D.memory[app+':'+m]}});document.getElementById('gain').textContent=fmt(100*(1-agg.equal_application_geomean_ratio))+'%';const counts=entries.map(e=>100*e.memory.allocation_call_reduction);const clean=entries.map(e=>100*(1-e.a.stages_median_ms.cleanup_ms/e.b.stages_median_ms.cleanup_ms));document.getElementById('alloc').textContent=Math.min(...counts).toFixed(0)+'–'+Math.max(...counts).toFixed(0)+'%';document.getElementById('cleanup').textContent=Math.min(...clean).toFixed(0)+'–'+Math.max(...clean).toFixed(0)+'%';document.getElementById('interval').textContent=agg.speedup.toFixed(2)+'× speedup · 95% paired bootstrap interval: '+fmt(100*(1-agg.ratio_ci95[1]))+'–'+fmt(100*(1-agg.ratio_ci95[0]))+'% less time';const max=Math.max(...entries.map(e=>keys.reduce((sum,k)=>sum+e.b.stages_median_ms[k],0)));document.getElementById('chart').innerHTML=entries.map(e=>'<div class="app"><div class="label"><strong>'+labels[e.app]+'</strong><span>'+fmt(e.b.compile_median_ms)+' → '+fmt(e.a.compile_median_ms)+' ms</span></div>'+[['Before',e.b],['After',e.a]].map(([label,v])=>'<div class="barrow"><span>'+label+'</span><div class="track">'+keys.map((k,i)=>'<div class="seg" style="background:'+colors[i]+';width:'+100*v.stages_median_ms[k]/max+'%" title="'+names[i]+': '+fmt(v.stages_median_ms[k])+' ms"></div>').join('')+'</div></div>').join('')+'</div>').join('');document.getElementById('times').innerHTML=entries.map(e=>'<tr><th>'+labels[e.app]+'</th><td>'+fmt(e.b.compile_median_ms)+' → '+fmt(e.a.compile_median_ms)+'</td>'+['lex_ms','parse_ms','cleanup_ms'].map(k=>'<td>'+fmt(e.b.stages_median_ms[k])+' → '+fmt(e.a.stages_median_ms[k])+'</td>').join('')+'</tr>').join('');document.getElementById('memory').innerHTML=entries.map(e=>'<tr><th>'+labels[e.app]+'</th><td>'+fmt(e.memory.baseline.peak_rss_bytes/2**20)+' → '+fmt(e.memory.arena.peak_rss_bytes/2**20)+'</td></tr>').join('')}draw();console.log('Three variants; six application/mode groups; all controls ready.');
</script></body></html>'''
page=page.replace('__SSA_ROWS__',rows).replace('__Q__',f'{q:.1f}').replace('__SQL__',f'{sql:.1f}').replace('__DATA__',json.dumps(data,separators=(',',':')))
(ROOT/'c-frontend-optimized-20261015.html').write_text(page)
